def count_passing_ways(n, m):
    # Initialize a 2D array to store the results of subproblems
    dp = [[0] * (m + 1) for _ in range(n)]

    # Initialize the first row of the dp table
    for i in range(n):
        dp[i][0] = 1

    # Fill in the dp table
    for i in range(1, m + 1):
        for j in range(n):
            # Case 1: Pass the ball to the left neighbor
            if j - 1 >= 0:
                dp[j][i] += dp[j - 1][i - 1]
            # Case 2: Pass the ball to the right neighbor
            if j + 1 < n:
                dp[j][i] += dp[j + 1][i - 1]

    # Return the number of passing ways
    return dp[0][m]

