    # Initialize a dynamic programming table to store the maximum volume
    # that can be occupied by any subset of the given items
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill in the table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            # If the current volume is greater than the volume of the current item,
            # then we cannot include the current item in the subset
            if i - volumes[j - 1] < 0:
                dp[i][j] = dp[i][j - 1]
            else:
